class DataStatistics4:
    """
    This is a class that performs advanced mathematical calculations and statistics, including correlation coefficient, skewness, kurtosis, and probability density function (PDF) for a normal distribution.
    """

    @staticmethod
    def correlation_coefficient(data1, data2):
        if len(data1) != len(data2) or len(data1) == 0:
            raise ValueError("Both datasets must have the same non-zero length.")

        mean1 = sum(data1) / len(data1)
        mean2 = sum(data2) / len(data2)

        covariance = sum((x - mean1) * (y - mean2) for x, y in zip(data1, data2)) / len(data1)
        std_dev1 = math.sqrt(sum((x - mean1) ** 2 for x in data1) / len(data1))
        std_dev2 = math.sqrt(sum((y - mean2) ** 2 for y in data2) / len(data2))

        if std_dev1 == 0 or std_dev2 == 0:
            raise ValueError("Standard deviation cannot be zero.")

        return covariance / (std_dev1 * std_dev2)

    @staticmethod
    def skewness(data):
        if len(data) == 0:
            raise ValueError("Data cannot be empty.")

        mean = sum(data) / len(data)
        std_dev = math.sqrt(sum((x - mean) ** 2 for x in data) / len(data))

        if std_dev == 0:
            raise ValueError("Standard deviation cannot be zero.")

        n = len(data)
        skewness = (sum((x - mean) ** 3 for x in data) / n) / (std_dev ** 3)
        return skewness

    @staticmethod
    def kurtosis(data):
        if len(data) == 0:
            raise ValueError("Data cannot be empty.")

        mean = sum(data) / len(data)
        std_dev = math.sqrt(sum((x - mean) ** 2 for x in data) / len(data))

        if std_dev == 0:
            raise ValueError("Standard deviation cannot be zero.")

        n = len(data)
        kurtosis = (sum((x - mean) ** 4 for x in data) / n) / (std_dev ** 4) - 3
        return kurtosis

    @staticmethod
    def pdf(data, mu, sigma):
        if len(data) == 0:
            raise ValueError("Data cannot be empty.")
        if sigma <= 0:
            raise ValueError("Standard deviation must be positive.")

        pdf_values = []
        for x in data:
            pdf = (1 / (math.sqrt(2 * math.pi) * sigma)) * math.exp(-((x - mu) ** 2) / (2 * sigma ** 2))
            pdf_values.append(pdf)

        return pdf_values

