class EightPuzzle:
    def __init__(self, initial_state):
        self.initial_state = initial_state
        self.goal_state = [[1, 2, 3], [4, 5, 6], [7, 8, 0]]

    def find_blank(self, state):
        for i in range(3):
            for j in range(3):
                if state[i][j] == 0:
                    return (i, j)
        raise ValueError("Invalid state: no blank tile found")

    def move(self, state, direction):
        i, j = self.find_blank(state)
        new_state = [row[:] for row in state]  # Create a deep copy of the state

        if direction == 'up' and i > 0:
            new_state[i][j], new_state[i-1][j] = new_state[i-1][j], new_state[i][j]
        elif direction == 'down' and i < 2:
            new_state[i][j], new_state[i+1][j] = new_state[i+1][j], new_state[i][j]
        elif direction == 'left' and j > 0:
            new_state[i][j], new_state[i][j-1] = new_state[i][j-1], new_state[i][j]
        elif direction == 'right' and j < 2:
            new_state[i][j], new_state[i][j+1] = new_state[i][j+1], new_state[i][j]
        else:
            raise ValueError(f"Invalid move direction: {direction}")

        return new_state

    def get_possible_moves(self, state):
        i, j = self.find_blank(state)
        moves = []
        if i > 0: moves.append('up')
        if i < 2: moves.append('down')
        if j > 0: moves.append('left')
        if j < 2: moves.append('right')
        return moves

    def solve(self):
        open_list = deque([(self.initial_state, [])])  # Queue of (state, path)
        visited = set()  # Track visited states

        while open_list:
            current_state, path = open_list.popleft()

            if current_state == self.goal_state:
                return path

            visited.add(tuple(map(tuple, current_state)))  # Convert state to hashable type

            for move in self.get_possible_moves(current_state):
                new_state = self.move(current_state, move)
                if tuple(map(tuple, new_state)) not in visited:
                    open_list.append((new_state, path + [move]))

        raise ValueError("No solution found")

from datetime import datetime

class EmailClient:
    def __init__(self, addr, capacity) -> None:
        self.addr = addr
        self.capacity = capacity
        self.inbox = []

    def send_to(self, recv, content, size):
        if recv.is_full_with_one_more_email(size):
            return False
        email = {
            'sender': self.addr,
            'receiver': recv.addr,
            'content': content,
            'size': size,
            'time': datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
            'state': 'unread'
        }
        recv.inbox.append(email)
        return True

    def fetch(self):
        for email in self.inbox:
            if email['state'] == 'unread':
                email['state'] = 'read'
                return email
        return None

    def is_full_with_one_more_email(self, size):
        return self.get_occupied_size() + size > self.capacity

    def get_occupied_size(self):
        return sum(email['size'] for email in self.inbox)

    def clear_inbox(self, size):
        while self.is_full_with_one_more_email(size) and self.inbox:
            self.inbox.pop(0)

