from decimal import Decimal

class ExpressionCalculator:
    def __init__(self):
        self.postfix_stack = deque()
        self.operat_priority = [0] * 128
        self.operat_priority[ord('+')] = 1
        self.operat_priority[ord('-')] = 1
        self.operat_priority[ord('*')] = 2
        self.operat_priority[ord('/')] = 2
        self.operat_priority[ord('%')] = 2
        self.operat_priority[ord('(')] = 0
        self.operat_priority[ord(')')] = 0

    @staticmethod
    def is_operator(c):
        return c in {'+', '-', '*', '/', '(', ')', '%'}

    def compare(self, cur, peek):
        return self.operat_priority[ord(cur)] >= self.operat_priority[ord(peek)]

    @staticmethod
    def transform(expression):
        return expression.replace(" ", "")

    def prepare(self, expression):
        expression = self.transform(expression)
        operator_stack = deque()
        postfix = []

        for char in expression:
            if char.isdigit():
                postfix.append(char)
            elif self.is_operator(char):
                if char == '(':
                    operator_stack.append(char)
                elif char == ')':
                    while operator_stack and operator_stack[-1] != '(':
                        postfix.append(operator_stack.pop())
                    operator_stack.pop()
                else:
                    while operator_stack and not self.compare(char, operator_stack[-1]):
                        postfix.append(operator_stack.pop())
                    operator_stack.append(char)

        while operator_stack:
            postfix.append(operator_stack.pop())

        self.postfix_stack = postfix

    @staticmethod
    def _calculate(first_value, second_value, current_op):
        first = Decimal(first_value)
        second = Decimal(second_value)

        if current_op == '+':
            return first + second
        elif current_op == '-':
            return first - second
        elif current_op == '*':
            return first * second
        elif current_op == '/':
            if second == 0:
                raise ZeroDivisionError("Division by zero is not allowed.")
            return first / second
        elif current_op == '%':
            return first % second

    def calculate(self, expression):
        self.prepare(expression)
        stack = deque()

        for token in self.postfix_stack:
            if token.isdigit():
                stack.append(token)
            else:
                second_value = stack.pop()
                first_value = stack.pop()
                result = self._calculate(first_value, second_value, token)
                stack.append(str(result))

        return float(stack.pop())

class Hotel:
    """
    This is a class as hotel management system, managing the booking, check-in, check-out, and availability of rooms in a hotel with different room types.
    """

    def __init__(self, name, rooms):
        """
        Initialize the three fields in Hotel System.
        """
        self.name = name
        self.available_rooms = rooms
        self.booked_rooms = {room_type: {} for room_type in rooms}

    def book_room(self, room_type, room_number, name):
        """
        Book rooms for a guest.
        """
        if room_type not in self.available_rooms or self.available_rooms[room_type] == 0:
            return False
        if room_number > self.available_rooms[room_type]:
            return self.available_rooms[room_type]

        self.available_rooms[room_type] -= room_number
        if name in self.booked_rooms[room_type]:
            self.booked_rooms[room_type][name] += room_number
        else:
            self.booked_rooms[room_type][name] = room_number

        return 'Success!'

    def check_in(self, room_type, room_number, name):
        """
        Check in a guest who has booked rooms.
        """
        if room_type not in self.booked_rooms or name not in self.booked_rooms[room_type]:
            return False
        if room_number > self.booked_rooms[room_type][name]:
            return False

        self.booked_rooms[room_type][name] -= room_number
        if self.booked_rooms[room_type][name] == 0:
            del self.booked_rooms[room_type][name]

    def check_out(self, room_type, room_number):
        """
        Check out rooms and update availability.
        """
        if room_type in self.available_rooms:
            self.available_rooms[room_type] += room_number
        else:
            self.available_rooms[room_type] = room_number

    def get_available_rooms(self, room_type):
        """
        Get the number of available rooms of a specific type.
        """
        return self.available_rooms.get(room_type, 0)

