            raise ValueError("x must be sorted in ascending order.")
        if not all(y[i] <= y[i + 1] for i in range(len(y) - 1)):
            raise ValueError("y must be sorted in ascending order.")

        z_interp = []
        for xi, yi in zip(x_interp, y_interp):
            if xi < x[0] or xi > x[-1] or yi < y[0] or yi > y[-1]:
                raise ValueError(f"Interpolation point ({xi}, {yi}) is out of bounds.")
            # Find the grid cell [x[i], x[i+1]] x [y[j], y[j+1]] where (xi, yi) lies
            for i in range(len(x) - 1):
                if x[i] <= xi <= x[i + 1]:
                    for j in range(len(y) - 1):
                        if y[j] <= yi <= y[j + 1]:
                            # Bilinear interpolation formula
                            t = (xi - x[i]) / (x[i + 1] - x[i])
                            u = (yi - y[j]) / (y[j + 1] - y[j])
                            z00 = z[j][i]
                            z01 = z[j + 1][i]
                            z10 = z[j][i + 1]
                            z11 = z[j + 1][i + 1]
                            zi = (1 - t) * (1 - u) * z00 + t * (1 - u) * z10 + (1 - t) * u * z01 + t * u * z11
                            z_interp.append(zi)
                            break
                    break
        return z_interp

class JobMarketplace:
    """
    This is a class that provides functionalities to publish positions, remove positions, submit resumes, withdraw resumes, search for positions, and obtain candidate information.
    """

    def __init__(self):
        self.job_listings = []
        self.resumes = []

    def post_job(self, job_title, company, requirements):
        """
        Add a job posting to the job_listings list.
        """
        if not isinstance(requirements, list):
            raise ValueError("Requirements must be a list.")

        job = {
            "job_title": job_title,
            "company": company,
            "requirements": requirements
        }

        if job not in self.job_listings:
            self.job_listings.append(job)

    def remove_job(self, job):
        """
        Remove a specific job posting from the job_listings list.
        """
        if job in self.job_listings:
            self.job_listings.remove(job)

    def submit_resume(self, name, skills, experience):
        """
        Add a resume to the resumes list.
        """
        if not isinstance(skills, list):
            raise ValueError("Skills must be a list.")

        resume = {
            "name": name,
            "skills": skills,
            "experience": experience
        }

        if resume not in self.resumes:
            self.resumes.append(resume)

    def withdraw_resume(self, resume):
        """
        Remove a specific resume from the resumes list.
        """
        if resume in self.resumes:
            self.resumes.remove(resume)

    def search_jobs(self, criteria):
        """
        Search for jobs that match a specific criterion.
        """
        return [
            job for job in self.job_listings
            if criteria in job["requirements"]
        ]

    def get_job_applicants(self, job):
        """
        Find resumes that match the requirements of a specific job.
        """
        def matches_requirements(resume, requirements):
            return all(req in resume["skills"] for req in requirements)

        return [
            resume for resume in self.resumes
            if matches_requirements(resume, job["requirements"])
        ]

import random

class MusicPlayer:
    """
    This is a class as a music player that provides to play, stop, add songs, remove songs, set volume, shuffle, and switch to the next or previous song.
    """

    def __init__(self):
        self.playlist = []
        self.current_song = None
        self.volume = 50

    def add_song(self, song):
        if song and isinstance(song, str):
            self.playlist.append(song)

    def remove_song(self, song):
        if song in self.playlist:
            self.playlist.remove(song)
            if self.current_song == song:
                self.current_song = None

    def play(self):
        if self.current_song:
            return self.current_song
        elif self.playlist:
            self.current_song = self.playlist[0]
            return self.current_song
        return False

    def stop(self):
        if self.current_song:
            self.current_song = None
            return True
        return False

    def switch_song(self):
        if self.playlist and self.current_song in self.playlist:
            current_index = self.playlist.index(self.current_song)
            if current_index < len(self.playlist) - 1:
                self.current_song = self.playlist[current_index + 1]
                return True
        elif self.playlist:
            self.current_song = self.playlist[0]
            return True
        return False

    def previous_song(self):
        if self.playlist and self.current_song in self.playlist:
            current_index = self.playlist.index(self.current_song)
            if current_index > 0:
                self.current_song = self.playlist[current_index - 1]
                return True
        return False

    def set_volume(self, volume):
        if isinstance(volume, int) and 0 <= volume <= 100:
            self.volume = volume
            return True
        return False

    def shuffle(self):
        if self.playlist:
            random.shuffle(self.playlist)
            return True
        return False

class NumberConverter:
    """
    The class allows to convert decimal to binary, octal, and hexadecimal respectively and vice versa.
    """

    @staticmethod
    def decimal_to_binary(decimal_num):
        """
        Convert a number from decimal format to binary format.
        :param decimal_num: int, decimal number
        :return: str, the binary representation of an integer.
        """
        if not isinstance(decimal_num, int):
            raise ValueError("Input must be an integer.")
        return bin(decimal_num)[2:] if decimal_num >= 0 else '-' + bin(abs(decimal_num))[2:]

    @staticmethod
    def binary_to_decimal(binary_num):
        """
        Convert a number from binary format to decimal format.
        :param binary_num: str, binary number
        :return: int, the decimal representation of binary number str.
        """
        if not isinstance(binary_num, str) or not binary_num.replace('-', '').isdigit() or not all(c in '01' for c in binary_num.replace('-', '')):
            raise ValueError("Input must be a valid binary string.")
        return int(binary_num, 2)

    @staticmethod
    def decimal_to_octal(decimal_num):
        """
        Convert a number from decimal format to octal format.
        :param decimal_num: int, decimal number
        :return: str, the octal representation of an integer.
        """
        if not isinstance(decimal_num, int):
            raise ValueError("Input must be an integer.")
        return oct(decimal_num)[2:] if decimal_num >= 0 else '-' + oct(abs(decimal_num))[2:]

    @staticmethod
    def octal_to_decimal(octal_num):
        """
        Convert a number from octal format to decimal format.
        :param octal_num: str, octal num
        :return: int, the decimal representation of octal number str.
        """
        if not isinstance(octal_num, str) or not octal_num.replace('-', '').isdigit() or not all(c in '01234567' for c in octal_num.replace('-', '')):
            raise ValueError("Input must be a valid octal string.")
        return int(octal_num, 8)

    @staticmethod
    def decimal_to_hex(decimal_num):
        """
        Convert a number from decimal format to hex format.
        :param decimal_num: int, decimal number
        :return hex_num: str, the hex representation of an integer.
        """
        if not isinstance(decimal_num, int):
            raise ValueError("Input must be an integer.")
        return hex(decimal_num)[2:] if decimal_num >= 0 else '-' + hex(abs(decimal_num))[2:]

    @staticmethod
    def hex_to_decimal(hex_num):
        """
        Convert a number from hex format to decimal format.
        :param hex_num: str, hex num
        :return: int, the decimal representation of hex number str.
        """
        if not isinstance(hex_num, str) or not hex_num.replace('-', '').isalnum() or not all(c in '0123456789abcdefABCDEF' for c in hex_num.replace('-', '')):
            raise ValueError("Input must be a valid hexadecimal string.")
        return int(hex_num, 16)

import PyPDF2

class PDFHandler:
    """
    The class allows merging multiple PDF files into one and extracting text from PDFs using PyPDF2 library.
    """

    def __init__(self, filepaths):
        """
        Takes a list of file paths filepaths as a parameter.
        It creates a list named readers using PyPDF2, where each reader opens a file from the given paths.
        """
        self.filepaths = filepaths
        self.readers = []
        for filepath in filepaths:
            try:
                reader = PyPDF2.PdfReader(filepath)
                self.readers.append(reader)
            except Exception as e:
                print(f"Error opening file {filepath}: {e}")

    def merge_pdfs(self, output_filepath):
        """
        Read files in self.readers which stores handles to multiple PDF files.
        Merge them to one pdf and update the page number, then save in disk.
        :param output_filepath: str, output file path to save to
        :return: str, "Merged PDFs saved at {output_filepath}" if successfully merged
        """
        if not self.readers:
            return "No valid PDF files to merge."

        try:
            pdf_writer = PyPDF2.PdfWriter()
            for reader in self.readers:
                for page in reader.pages:
                    pdf_writer.add_page(page)

            with open(output_filepath, 'wb') as output_file:
                pdf_writer.write(output_file)

            return f"Merged PDFs saved at {output_filepath}"
        except Exception as e:
            return f"Error merging PDFs: {e}"

    def extract_text_from_pdfs(self):
        """
        Extract text from pdf files in self.readers
        :return pdf_texts: list of str, each element is the text of one pdf file
        """
        pdf_texts = []
        for reader in self.readers:
            try:
                text = ""
                for page in reader.pages:
                    text += page.extract_text()
                pdf_texts.append(text)
            except Exception as e:
                pdf_texts.append(f"Error extracting text: {e}")
        return pdf_texts

import re

class RegexUtils:
    """
    The class provides to match, find all occurrences, split, and substitute text using regular expressions. It also includes predefined patterns, validating phone numbers and extracting email addresses.
    """

    def match(self, pattern, text):
        return bool(re.fullmatch(pattern, text))

    def findall(self, pattern, text):
        return re.findall(pattern, text)

    def split(self, pattern, text):
        return re.split(pattern, text)

    def sub(self, pattern, replacement, text):
        return re.sub(pattern, replacement, text)

    def generate_email_pattern(self):
        return r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b'

    def generate_phone_number_pattern(self):
        return r'\b\d{3}-\d{3}-\d{4}\b'

    def generate_split_sentences_pattern(self):
        return r'[.!?][\s]{1,2}(?=[A-Z])'

    def split_sentences(self, text):
        pattern = self.generate_split_sentences_pattern()
        return re.split(pattern, text)

    def validate_phone_number(self, phone_number):
        pattern = self.generate_phone_number_pattern()
        return bool(re.fullmatch(pattern, phone_number))

    def extract_email(self, text):
        pattern = self.generate_email_pattern()
        return re.findall(pattern, text)

class ShoppingCart:
    """
    The class manages items, their prices, quantities, and allows to add, remove, view items, and calculate the total price.
    """

    def __init__(self):
        """
        Initialize the items representing the shopping list as an empty dictionary
        """
        self.items = {}

    def add_item(self, item, price, quantity=1):
        """
        Add item information to the shopping list items, including price and quantity. The default quantity is 1.
        """
        if item in self.items:
            # Update the quantity if the item already exists
            self.items[item]["quantity"] += quantity
        else:
            # Add the item with price and quantity
            self.items[item] = {"price": price, "quantity": quantity}

    def remove_item(self, item, quantity=1):
        """
        Subtract the specified quantity of item from the shopping list items.
        """
        if item in self.items:
            # Reduce the quantity
            self.items[item]["quantity"] -= quantity
            # If quantity is 0 or less, remove the item entirely
            if self.items[item]["quantity"] <= 0:
                del self.items[item]
        else:
            print(f"Item '{item}' not found in the shopping cart.")

    def view_items(self) -> dict:
        """
        Return the current shopping list items.
        """
        return self.items

    def total_price(self) -> float:
        """
        Calculate the total price of all items in the shopping list.
        """
        total = 0.0
        for item, details in self.items.items():
            total += details["price"] * details["quantity"]
        return total

class SQLQueryBuilder:
    """
    This class provides to build SQL queries, including SELECT, INSERT, UPDATE, and DELETE statements. 
    """

    @staticmethod
    def select(table, columns='*', where=None):
        if not table:
            raise ValueError("Table name is required.")

        # Handle columns
        if columns == '*' or not columns:
            columns_part = '*'
        else:
            columns_part = ', '.join(columns)

        # Start query
        query = f"SELECT {columns_part} FROM {table}"

        # Handle WHERE clause
        if where:
            conditions = [f"{key}='{value}'" for key, value in where.items()]
            query += " WHERE " + " AND ".join(conditions)

        return query

    @staticmethod
    def insert(table, data):
        if not table:
            raise ValueError("Table name is required.")
        if not data:
            raise ValueError("Data for insertion is required.")

        # Extract columns and values
        columns = ', '.join(data.keys())
        values = ', '.join(f"'{value}'" for value in data.values())

        # Construct query
        query = f"INSERT INTO {table} ({columns}) VALUES ({values})"
        return query

    @staticmethod
    def delete(table, where=None):
        if not table:
            raise ValueError("Table name is required.")

        # Start query
        query = f"DELETE FROM {table}"

        # Handle WHERE clause
        if where:
            conditions = [f"{key}='{value}'" for key, value in where.items()]
            query += " WHERE " + " AND ".join(conditions)

        return query

    @staticmethod
    def update(table, data, where=None):
        if not table:
            raise ValueError("Table name is required.")
        if not data:
            raise ValueError("Data for update is required.")

        # Handle SET clause
        set_part = ', '.join(f"{key}='{value}'" for key, value in data.items())

        # Start query
        query = f"UPDATE {table} SET {set_part}"

        # Handle WHERE clause
        if where:
            conditions = [f"{key}='{value}'" for key, value in where.items()]
            query += " WHERE " + " AND ".join(conditions)

        return query

import math
from collections import Counter

class Statistics3:
    """
    This is a class that implements methods for calculating indicators such as median, mode, correlation matrix, and Z-score in statistics.
    """

    @staticmethod
    def median(data):
        if not data:
            return None
        data = sorted(data)
        n = len(data)
        mid = n // 2
        if n % 2 == 0:
            return (data[mid - 1] + data[mid]) / 2
        else:
            return data[mid]

    @staticmethod
    def mode(data):
        if not data:
            return []
        freq = Counter(data)
        max_count = max(freq.values())
        return [key for key, count in freq.items() if count == max_count]

    @staticmethod
    def correlation(x, y):
        if len(x) != len(y):
            raise ValueError("Lists must have the same length")
        if len(x) < 2:
            return None
        mean_x = Statistics3.mean(x)
        mean_y = Statistics3.mean(y)
        std_x = Statistics3.standard_deviation(x)
        std_y = Statistics3.standard_deviation(y)
        if std_x == 0 or std_y == 0:
            return None
        covariance = sum((xi - mean_x) * (yi - mean_y) for xi, yi in zip(x, y)) / len(x)
        return covariance / (std_x * std_y)

    @staticmethod
    def mean(data):
        if not data:
            return None
        return sum(data) / len(data)

    @staticmethod
    def correlation_matrix(data):
        if not data or any(len(row) != len(data[0]) for row in data):
            raise ValueError("All sublists must have the same length")
        n = len(data)
        matrix = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                matrix[i][j] = Statistics3.correlation(data[i], data[j])
        return matrix

    @staticmethod
    def standard_deviation(data):
        if not data:
            return None
        mean_value = Statistics3.mean(data)
        variance = sum((x - mean_value) ** 2 for x in data) / len(data)
        return math.sqrt(variance)

    @staticmethod
    def z_score(data):
        if not data:
            return []
        mean_value = Statistics3.mean(data)
        std_dev = Statistics3.standard_deviation(data)
        if std_dev == 0:
            return [0] * len(data)
        return [(x - mean_value) / std_dev for x in data]

class StockPortfolioTracker:
    def __init__(self, cash_balance):
        self.portfolio = []
        self.cash_balance = cash_balance

    def add_stock(self, stock):
        for s in self.portfolio:
            if s["name"] == stock["name"]:
                s["quantity"] += stock["quantity"]
                return
        self.portfolio.append(stock)

    def remove_stock(self, stock):
        for s in self.portfolio:
            if s["name"] == stock["name"] and s["quantity"] == stock["quantity"]:
                self.portfolio.remove(s)
                return True
        return False

    def buy_stock(self, stock):
        total_cost = stock["price"] * stock["quantity"]
        if self.cash_balance >= total_cost:
            self.cash_balance -= total_cost
            self.add_stock(stock)
            return True
        return False

    def sell_stock(self, stock):
        for s in self.portfolio:
            if s["name"] == stock["name"] and s["quantity"] >= stock["quantity"]:
                s["quantity"] -= stock["quantity"]
                self.cash_balance += stock["price"] * stock["quantity"]
                if s["quantity"] == 0:
                    self.portfolio.remove(s)
                return True
        return False

    def calculate_portfolio_value(self):
        total_value = self.cash_balance
        for stock in self.portfolio:
            total_value += stock["price"] * stock["quantity"]
        return total_value

