        elif tmp_units == 'celsius' and current_units == 'fahrenheit':
            self.temperature = self.fahrenheit_to_celsius()
        elif tmp_units not in ['celsius', 'fahrenheit']:
            raise ValueError(f"Invalid temperature units: {tmp_units}")

        return self.temperature, self.weather

    def set_city(self, city):
        """
        Set the city of the weather system.
        """
        if not isinstance(city, str) or not city.strip():
            raise ValueError("City must be a non-empty string.")
        self.city = city

    def celsius_to_fahrenheit(self):
        """
        Convert the temperature from Celsius to Fahrenheit.
        """
        if self.temperature is None:
            raise ValueError("Temperature is not set.")
        return round((self.temperature * 9/5) + 32, 1)

    def fahrenheit_to_celsius(self):
        """
        Convert the temperature from Fahrenheit to Celsius.
        """
        if self.temperature is None:
            raise ValueError("Temperature is not set.")
        return round((self.temperature - 32) * 5/9, 1)

def text2int(self, textnum):
    textnum = textnum.lower().strip()  # Normalize input
    if not self.is_valid_input(textnum):
        raise ValueError(f"Invalid input: {textnum}")

    words = textnum.replace("-", " ").split()  # Handle hyphenated numbers
    current = result = 0
    for word in words:
        if word in self.ordinal_words:
            current += self.ordinal_words[word]
        elif word in self.numwords:
            scale, increment = self.numwords[word]
            current = current * scale + increment
            if scale > 100:
                result += current
                current = 0
        else:
            for ending, replacement in self.ordinal_endings:
                if word.endswith(ending):
                    word = word[: -len(ending)] + replacement
                    if word in self.numwords:
                        scale, increment = self.numwords[word]
                        current = current * scale + increment
                        break
            else:
                raise ValueError(f"Invalid word: {word}")

    return str(result + current)

import zipfile
import os


class ZipFileProcessor:
    """
    This is a compressed file processing class that provides the ability to read and decompress compressed files
    """

    def __init__(self, file_name):
        """
        Initialize file name
        :param file_name:string
        """
        self.file_name = file_name

    def read_zip_file(self):
        """
        Get open file object
        :return:If successful, returns the open file object; otherwise, returns None
        """
        try:
            return zipfile.ZipFile(self.file_name, 'r')
        except (FileNotFoundError, zipfile.BadZipFile):
            return None

    def extract_all(self, output_path):
        """
        Extract all zip files and place them in the specified path
        :param output_path: string, The location of the extracted file
        :return: True or False, representing whether the extraction operation was successful
        """
        zip_file = self.read_zip_file()
        if not zip_file:
            return False
        try:
            zip_file.extractall(output_path)
            zip_file.close()
            return True
        except Exception:
            return False

    def extract_file(self, file_name, output_path):
        """
        Extract the file with the specified name from the zip file and place it in the specified path
        :param file_name:string, The name of the file to be uncompressed
        :param output_path:string, The location of the extracted file
        :return: True or False, representing whether the extraction operation was successful
        """
        zip_file = self.read_zip_file()
        if not zip_file:
            return False
        try:
            if file_name in zip_file.namelist():
                zip_file.extract(file_name, output_path)
                zip_file.close()
                return True
            else:
                zip_file.close()
                return False
        except Exception:
            return False

    def create_zip_file(self, files, output_file_name):
        """
        Compress the specified file list into a zip file and place it in the specified path
        :param files:list of string, List of files to compress
        :param output_file_name: string, Specified output path
        :return:True or False, representing whether the compression operation was successful
        """
        try:
            with zipfile.ZipFile(output_file_name, 'w') as zip_file:
                for file in files:
                    if os.path.exists(file):
                        zip_file.write(file, os.path.basename(file))
                    else:
                        return False
            return True
        except Exception:
            return False
